
local itmu=[==[]==]
local cso=
(function(...)
local kxnnx={141,76,143,138,138,252,91,112,147,196,48,34,130,27,147,92,144,147,46,136,3,223,229,169}
local iu=bit32 or bit
local ciwuo=iu.bxor
for akkqx=1,#kxnnx do kxnnx[akkqx]=ciwuo(kxnnx[akkqx],(136*akkqx+28)%256) end
local xzhb="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local rppor={}
for eoppc=1,#xzhb do rppor[xzhb:byte(eoppc)]=eoppc-1 end
local function vo(str)
  local R={} local acc,nb=0,0
  for yvh=1,#str do
    local v=rppor[str:byte(yvh)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function yrgid(key,data)
  local S={} for uldm=0,255 do S[uldm]=uldm end
  local j=0
  for wrvfm=0,255 do
    j=(j+S[wrvfm]+key[(wrvfm%#key)+1])%256
    S[wrvfm],S[j]=S[j],S[wrvfm]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(ciwuo(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=yrgid(kxnnx,vo(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local yrp=nf()
return function(big) return yrp(big) end
end)(...)

return cso(itmu)
